tasks.solution:
sessions = {'s-41': {'user': 'mina', 'csrf': 'k93tq'}}
emails = {'mina': 'mina@mail.kr'}

def change_email(cookie, form):
    session = sessions[cookie]
    # 이 주석 아래에 폼의 토큰을 세션의 토큰과 비교하세요.
    # 쿠키는 자동으로 붙지만 토큰은 서버가 내준 폼에만 있어요. 다르면 바꾸지 않아요.
    if form.get('token') != session['csrf']:
        return 'refused'
    emails[session['user']] = form['email']
    return 'changed'

# 미나의 브라우저가 다른 사이트에서 보낸 요청이에요. 쿠키 s-41은 자동으로 붙었어요.
form = {'email': 'evil@attack.kr'}
print(change_email('s-41', form), emails['mina'])

