PASSWORDS = {'mina': 'blue-77', 'jun': 'tiger#2'}

def login(user, password):
    if user not in PASSWORDS:
        return False
    # 통과 경로는 저장된 비밀번호와 같을 때 하나뿐이에요.
    return PASSWORDS[user] == password

# 접속 기록에 남은 로그인 시도예요. 각 시도가 통과했는지 다시 돌려 봐요.
